  // ---------- Mensagem (WhatsApp e Telegram) ----------
  /** Vai trocando o modelo de texto para as mensagens não ficarem repetidas */
  function proximoEstilo(atual) {
    const ks = Object.keys(MODELOS_TEXTO); let ult = "";
    try { ult = atual || localStorage.getItem("miga_ult_estilo") || ""; } catch (e) { ult = atual || ""; }
    const k = ks[(ks.indexOf(ult) + 1) % ks.length];
    try { localStorage.setItem("miga_ult_estilo", k); } catch (e) { /* segue */ }
    return k;
  }
  /** Mensagem pronta que acompanha o modelo (ou a campanha / título próprio) da arte. Para mudar, edite no lápis. */
  function usarModeloTexto() {
    const it = wzItem(); if (!it) return;
    it.estiloTexto = "tema"; it.texto = mensagemWhats(it, { modelo: wz.modelo, camp: wz.camp, titulo: wz.tituloArte }); it.textoEditado = false; salvarFila();
  }
  /** Mensagem do WhatsApp (grupos e canal) de um produto, no modelo/campanha escolhidos */
  function mensagemWhats(it, base = {}) {
    const p = { nome: limparNome(it.nome), precoAntigo: it.precoAntigo, precoNovo: it.precoNovo, link: it.link, categoria: it.categoria || "outros", loja: it.loja, cupom: it.cupom || "" };
    const LG = LEGENDA_REELS[base.modelo] || LEGENDA_REELS.achadinho, C = CAMPANHAS[base.camp];
    const abre = base.titulo ? `✨ *${String(base.titulo).replace(/[*]/g, "").replace(/\s*\n\s*/g, " ")}*` : C ? C.chamada : LG.um("").replace(/\s{2,}/g, " ").trim();
    const preco = p.precoAntigo ? `~de ${brl(p.precoAntigo)}~ por *${brl(p.precoNovo)}*` : `por apenas *${brl(p.precoNovo)}*`;
    const off = p.precoAntigo && p.precoAntigo > p.precoNovo ? ` (${Math.round((1 - p.precoNovo / p.precoAntigo) * 100)}% OFF)` : "";
    const corpo = `✨ *${p.nome}*\n\n💸 ${preco}${off}${p.cupom ? `\n🎟️ Usa o cupom *${p.cupom}*` : ""}\n\n${FRASES[p.categoria] || FRASES.outros}\n\n${linkLoja(p.loja, p.link)}\n\nCorre que promoção boa assim acaba rapidinho! ⏳🌸`;
    return comConvite(`${abre}\n\n${corpo}`);
  }
  /** Manda direto para o WhatsApp: a foto do produto (limpa, sem selo) + a mensagem pronta */
  async function enviarProdutoNoWhats(it, base) {
    const texto = it.textoEditado && it.texto ? it.texto : mensagemWhats(it, base);
    let foto = null; try { if (it.imagem) foto = await converterImagem(await arquivoDaImagem(it.imagem)); /* grupo e canal: foto limpa, sem o selo da loja */ } catch (e) { foto = null; }
    let r = await compartilharArquivo(foto, comLoja(texto, it.loja, it.link));
    if (r === "sem") { await copiarTexto(texto); abrirWhatsApp(texto); r = "aberto"; }
    if (r === "cancelado") return false;
    marcarPostado(it, "whatsapp", "WhatsApp"); return true;
  }
  /* Cores em sequência (Creme → Rosa → Branco → Preto): guarda a do último post e o próximo começa na seguinte */
  const ORDEM_CORES = ["creme", "rosa", "branco", "preto"];
  function guardarCorUsada(cor) { if (!ORDEM_CORES.includes(cor)) return; try { localStorage.setItem("miga_ult_cor", cor); } catch (e) { /* segue */ } }
  function proximaCor() { let u = ""; try { u = localStorage.getItem("miga_ult_cor") || ""; } catch (e) { /* segue */ } const i = ORDEM_CORES.indexOf(u); return ORDEM_CORES[(i + 1) % ORDEM_CORES.length]; }
  $("#wzCorpo").addEventListener("click", (e) => {
    const pt = e.target.closest("#rPostar, #kPostar, #vdPostar"); if (!pt) return;
    if (wz.canal === "reels") { const R = rr(); itensReels().forEach((it) => marcarPostado(it, "instagram", R.carrossel ? "Carrossel" : "Reels")); }
    if (wz.canal === "video") { const it = vdItem(); if (it) marcarPostado(it, "instagram", "Vídeo"); }
  }, true);
  $("#wzCorpo").addEventListener("click", (e) => { if (e.target.closest("#rPostar, #rBaixar, #vdPostar, #vdBaixar, #kPostar, #kBaixar, #wzPostar, #wzBaixar, #rtPostar")) { try { guardarCorUsada(estLer().cor); } catch (er) { /* segue */ } } }, true);
  /** Marca o produto como postado (sai da Lista e vai para o Histórico, com data e onde) */
  function marcarPostado(it, canal, onde) {
    it.feito = { ...(it.feito || {}), [canal]: true }; it.postadoEm = Date.now();
    it.ondePostou = [...new Set([...(it.ondePostou || []), onde])]; salvarFila(true); contarFila();
  }
  async function registrarCompartilhado(canal, onde) {
    try { guardarCorUsada(estLer().cor); } catch (e) { /* segue */ }
    const it = wzItem(); if (!it) return;
    marcarPostado(it, canal, onde);
    const p = { nome: limparNome(it.nome), precoAntigo: it.precoAntigo, precoNovo: it.precoNovo, link: it.link, categoria: it.categoria || "outros", loja: it.loja, cupom: it.cupom || "" };
    try {
      let h = it.histId ? await dados.pegar(it.histId) : null;
      if (!h) { h = { id: novoId(), criadoEm: Date.now(), produto: p, texto: it.texto || "", imagem: it.imagem || "", enviadoPara: [] }; it.histId = h.id; salvarFila(true); }
      h.produto = p; if (it.texto) h.texto = it.texto; if (it.imagem) h.imagem = it.imagem;
      if (!h.enviadoPara.includes(onde)) h.enviadoPara.push(onde);
      h.ultimoEnvio = Date.now();
      await dados.salvar(h); atualizarContadores();
    } catch (e) { /* segue */ }
  }
  async function enviarWhats(modo) {
    const it = wzItem(), texto = it.texto;
    if (modo === "foto" && noComputador()) {
      // Computador: a foto vai para a área de transferência e o WhatsApp abre com o texto pronto
      const png = (async () => converterImagem(await arquivoDaImagem(it.imagem), "image/png"))();
      let copiou = false;
      try { await navigator.clipboard.write([new ClipboardItem({ "image/png": png.then((f) => f || Promise.reject()) })]); copiou = true; } catch (e) { copiou = false; }
      abrirWhatsApp(texto);
      toast(copiou ? "A foto foi copiada: na conversa do WhatsApp, aperte Ctrl+V para colar a foto e envie com o texto" : "O WhatsApp abriu com o texto. Para a foto, use “Baixar” e arraste para a conversa");
      registrarCompartilhado("whatsapp", "WhatsApp");
      return;
    }
    if (modo === "foto") {
      const arq = it.imagem ? await converterImagem(await arquivoDaImagem(it.imagem)) : null;
      if (arq && navigator.canShare && navigator.canShare({ files: [arq], text: texto })) {
        try { await navigator.share({ files: [arq], text: texto }); registrarCompartilhado("whatsapp", "WhatsApp (com foto)"); return; }
        catch (e) { if (e.name === "AbortError") return; }
      }
      if (await copiarTexto(texto)) toast("Texto copiado — no WhatsApp, envie a foto e cole o texto");
      registrarCompartilhado("whatsapp", "WhatsApp");
    } else if (modo === "texto") { abrirWhatsApp(texto); registrarCompartilhado("whatsapp", "WhatsApp"); }
    else if (await copiarTexto(texto)) { toast("Texto copiado"); registrarCompartilhado("whatsapp", "Copiado"); }
  }
  async function enviarGrupo(id) {
    const it = wzItem(), g = (config.grupos || []).find((x) => x.id === id);
    if (!g) return;
    const ok = await copiarTexto(it.texto);
    it.enviadoGrupos = [...new Set([...(it.enviadoGrupos || []), id])];
    registrarCompartilhado("whatsapp", g.nome);
    if (g.link) { window.open(g.link, "_blank", "noopener"); toast(ok ? `Mensagem copiada — cole no grupo ${g.nome}` : "Não consegui copiar"); }
    else toast(ok ? "Mensagem copiada: abra o grupo no WhatsApp e cole" : "Não consegui copiar");
    mostrarPasso();
  }
  function abrirTelegram() {
    const it = wzItem();
    const texto = textoCanal(it.texto).split(it.link).join("").trim();
    window.open(`https://t.me/share/url?url=${encodeURIComponent(it.link)}&text=${encodeURIComponent(texto)}`, "_blank", "noopener");
    registrarCompartilhado("telegram", "Telegram");
  }

  // ---------- Instagram (montagem pronta, sem @) ----------
  async function prepararFoto(it) {
    await carregarMarca();
    if (it && !(it.id in ppFotos) && it.imagem) {
      try { const arq = await arquivoDaImagem(it.imagem); ppFotos[it.id] = arq ? await createImageBitmap(arq) : null; } catch (e) { ppFotos[it.id] = null; }
    }
  }
